from .base_cl_tool import BaseClToolInterface


class TestModelInterface(BaseClToolInterface):
    """Keywords for test model related commands."""

    def start_rx_test_model(self, model, cell_id, duration, offset, interval, timeout='1min', **kwargs):
        """
        Checks RX Test Model in one or multiple sites.

        :param string model: Test model
        :param int cell_id: Local cell id
        :param int duration: Test duration
        :param int offset: Resource block offset for RX test
        :param int interval: Reporting interval for RX test
        :return: Path(s) of collected file(s).
        :rtype: list
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'type': 'rx', 'testmodel': model,
                  'cellid': cell_id, 'duration': duration, 'offset': offset, 'interval': interval}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='testmodel',
                                               params=params, trs_ip=ne, flags=flags)

    def start_tx_test_model(self, model, cell_id, duration, phycellid, timeout='1min', **kwargs):
        """
        Checks TX Test Model in one or multiple sites.

        :param string model: Test model
        :param int cell_id: Local cell id
        :param int duration: Test duration
        :param int phycellid: Physical cell id for TX test
        :return: Path(s) of collected file(s).
        :rtype: list
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout, 'type': 'tx', 'testmodel': model,
                  'cellid': cell_id, 'duration': duration, 'phycellid': phycellid}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='testmodel',
                                               params=params, trs_ip=ne, flags=flags)
